#!/usr/bin/env python3
"""Source-limit five Saussure items to the retrieved Cours passages."""
import json,html
import v9_apply_batch1 as b
import quiz_audit as qa
prior=json.loads((b.OUT/'changes.json').read_text());assert len(prior)==525
_,Q,A=qa.audit(str(b.DST));extra=[];D=json.loads((b.OUT/'decisions.json').read_text())
def item(k,stem,opts,exps,ans,why,verdicts):
 for field,vs in [('stem',[stem]),('options',opts),('explanations',exps)]:
  for i,new in enumerate(vs):
   old=Q[k]['stem'] if field=='stem' else Q[k]['opts'][i] if field=='options' else A['A_'+k[2:]]['txt'][i]
   extra.append(dict(id=k,field=field,index=None if field=='stem' else i,before=html.unescape(old),after=new,reason=why,sources=['S70'],applied=True,before_version='第31修正バッチ作業稿'))
 D[k].update(status='確認済み',fixes_applied=True,independent_answer=ans,sources=['S70'],option_verdicts=verdicts,reason=why,stem_review='一般言語学講義の指定部分で述べられた学説を問う。現代言語学全体の合意として扱わない。',explanation_review='原著再録の序論III–IV、第一部I、第二部III–IVの該当本文に全肢・全解説を照合。取得範囲はS70を参照。',unresolved='',multiple_correct_risk=f'なし：{ans}のみ指定した記述に一致',no_correct_risk=f'なし：独立正答{ans}')
item('Q_5_001','ソシュール『一般言語学講義』第一部第一章の言語記号について、適切な説明はどれか。',
 ['言語記号は、心理的な聴覚映像であるシニフィアンと、概念であるシニフィエの結合として説明される。','言語記号は概念だけで構成され、聴覚映像は記号の構成要素に含まれない。','シニフィアンは外界の物体そのものであり、シニフィエは文字の形である。','聴覚映像と概念の結びつきは自然の必然によって決まり、言語によって異なることはない。'],
 ['第一部第一章は、概念と聴覚映像の結合を言語記号とし、それぞれをシニフィエとシニフィアンと呼びます。聴覚映像は物理的な音そのものではなく心理的な表象です。','同章では概念と聴覚映像の双方が記号を構成します。概念だけとする説明は一方を落としています。','同章の概念と聴覚映像の説明に一致しません。外界の物体や文字の形をそれぞれの定義にする説明ではありません。','同章は、概念と聴覚映像の結びつきに自然的な必然性がないという恣意性を述べます。選択肢はその説明と逆です。'],1,
 '原著にないコイン比喩と指示物の補助用語を撤去。聴覚映像と物理的音を区別し、原著の二側面の定義に限定した。',
 ['原著の概念／聴覚映像の結合に一致して正しい','聴覚映像を除外して誤り','心理的な二側面を物体／文字へ置換して誤り','恣意性を自然必然に逆転して誤り'])
item('Q_5_002','ソシュール『一般言語学講義』第一部第一章で述べられる「言語記号の恣意性」について、適切な説明はどれか。',
 ['言語には文法規則がなく、話し手は気分だけで音をランダムに並べられるという意味である。','共同体で用いられている記号を、話し手個人が自由な選択だけで変えられるという意味である。','シニフィアンとシニフィエの結びつきに、自然的に必然な理由がないという意味である。','擬音語は自然音を完全に同一に写すため、どの言語でも必ず同じ形になるという意味である。'],
 ['恣意性は記号の二側面の結びつきについての説明です。文法規則が存在しないという定義ではありません。','原著は、恣意的という語を話し手の自由選択と混同しないよう注意しています。個人が勝手に既存の記号を変えられるという意味ではありません。','原著は、概念と聴覚映像の間に自然的な結びつきがないことを恣意性として説明します。','原著は、擬音語も音の近似的な模倣であり、慣習的な面を持つと説明します。すべての言語で必ず同じ形になるという説明は一致しません。'],3,
 '犬の呼称と鳴き声の個別言語例の未照合を残さないよう撤去。原著の定義、個人の自由選択ではない点、擬音語の近似性と慣習性に限定した。',
 ['記号の結合と規則不存在を混同して誤り','原著の自由選択ではないという注意に反して誤り','自然的必然の不存在という定義に一致して正しい','擬音の近似性と慣習性を排除して誤り'])
item('Q_5_003','ソシュール『一般言語学講義』第二部第四章の、言語による思考と音の分節について、適切な説明はどれか。',
 ['思考と音が結びつくことで、両方に相互に対応する単位の区切りが生じると説明される。','概念の境界は言語と無関係にすべて確定しており、言語は既成の概念へ名前札を貼るだけだと説明される。','言語の単位は音だけで決まり、概念との結びつきは単位の成立に関係しないと説明される。','どの言語でもすべての語の概念範囲が一致し、言語間の価値の違いは存在しないと説明される。'],
 ['第二部第四章は、思考と音の結合によって相互の区切りが生じ、言語の単位が形成されると説明します。これは思考と音についての学説であり、物理世界そのものが言語以前には存在しないという主張ではありません。','第一部第一章と第二部第四章は、概念がすべて先に確定していて言語が名付けるだけという見方を批判しています。','原著は思考と音の結合による相互の区切りを述べています。音だけで単位が決まるとする説明は一側面を除外しています。','第二部第四章は、似た意味を持つ語でも言語体系内の価値が一致しない例を挙げます。すべての概念範囲が一致するという説明ではありません。'],1,
 '言語以前の世界全体が無定形という過大な帰属を撤去。原著が論じる思考と音の分節に範囲を限定し、足／脚と生物分類の未照合例を削除。',
 ['思考と音の相互の区切りに一致して正しい','原著が批判する既成概念への名付けに逆転して誤り','思考の側面を除外して誤り','言語間の価値の相違を否定して誤り'])
item('Q_5_005','ソシュール『一般言語学講義』序論第三・第四章の、ラングとパロールの区別について、適切な説明はどれか。',
 ['ラングを社会的な言語体系、パロールを個人的な実行として区別し、両者は相互に依存すると説明される。','ラングは各人の個別の発話行為だけを意味し、社会的な体系ではないと説明される。','ラングとパロールは互いを必要とせず、完全に独立して成立すると説明される。','パロールは共同体に共有された言語体系であり、個人的な実行とは区別されると説明される。'],
 ['序論は、社会的なラングと個人的なパロールを区別するとともに、両者の相互依存を述べます。区別することは、関係がないとすることではありません。','個別の実行はパロールの側の説明です。ラングの社会的な側面と逆になっています。','序論第四章は、パロールの理解にラングが必要で、ラングの成立・変化にもパロールが関わると説明します。完全な独立とは述べていません。','共同体に共有された体系はラングの側の説明です。パロールは個人的な実行の側として区別されます。'],1,
 '言語学の真の対象はラングだけという主張を現代の総意へ拡張しないよう撤去。原著の区別と相互依存に限定して問う。',
 ['社会／個人の区別と相互依存に一致して正しい','ラングをパロールの側へ逆転して誤り','原著の相互依存を否定して誤り','パロールをラングの側へ逆転して誤り'])
item('Q_5_006','ソシュール『一般言語学講義』第二部第四章の、言語記号の「価値」について、適切な説明はどれか。',
 ['他の語や体系が変わっても、ある語の価値は必ず不変である。','ある語の価値は、言語体系内の他の語との関係や差異によって定まる。','ある語の価値は、体系から切り離した辞書的意味だけで完全に決まる。','ある語の価値には概念の側面がなく、物理的な音だけが関わる。'],
 ['原著は、近い意味を持つ語が相互に限定し合うことや、ある語がなければ競合する語の範囲が変わることを説明します。他の語の変化が無関係という説明は逆です。','原著は、語を孤立させず、体系内の他の語と比較して価値を捉えます。価値は他の語との関係から定まります。','原著は、ある概念を表すと確認するだけでは価値が定まらず、他の語との比較も必要と説明します。孤立した意味だけでは不十分です。','同章は価値を概念的側面と音の側面の双方から論じます。概念を除外し、物理的な音だけで価値を決める説明ではありません。'],2,
 '羊／羊肉の比喩を全言語への事実として読ませないよう撤去。原著の相互限定と他の語との比較に全内容を限定し、金額と価値観の混同を除いた。',
 ['他の語による相互限定を否定して誤り','原著の体系内の比較・差異に一致して正しい','他の語との比較を不要とし誤り','原著の概念的側面を除外して誤り'])
(b.OUT/'changes_batch32.json').write_text(json.dumps(extra,ensure_ascii=False,indent=2)+'\n')
(b.OUT/'changes.json').write_text(json.dumps(prior+extra,ensure_ascii=False,indent=2)+'\n')
(b.OUT/'decisions.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
p=b.OUT/'sources.md';p.write_text(p.read_text()+'\n| S70 | Saussure, Cours de linguistique générale（1916）、Bally・Sechehaye・Riedlinger編集、Payot1971原著再録：[序論](https://fr.wikisource.org/wiki/Cours_de_linguistique_g%C3%A9n%C3%A9rale/Introduction)、[第一部](https://fr.wikisource.org/wiki/Cours_de_linguistique_g%C3%A9n%C3%A9rale/Premi%C3%A8re_partie)、[第二部](https://fr.wikisource.org/wiki/Cours_de_linguistique_g%C3%A9n%C3%A9rale/Deuxi%C3%A8me_partie) | 序論III–IVの社会／個人と相互依存、第一部I§1–2の二側面・恣意性・擬音、第二部IIIの価値とIV§1–3の思考／音の分節・他の語との比較を原著転記本文で取得・精読。媒体の百科説明ではなく原著本文を照合。未照合の補助比喩・個別言語例を採用文面から撤去。 | Q_5_001、002、003、005、006 |\n')
print('Recorded',len(extra),'repairs')
